import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Profile = () => {
  const { 
    user, 
    logout, 
    cart, 
    removeFromCart, 
    favorites, 
    removeFromFavorites, 
    orders, 
    createOrder, 
    cancelOrder 
  } = useAuth();

  const navigate = useNavigate();
  const location = useLocation();
  const [activeTab, setActiveTab] = useState('profile');
  const [checkoutData, setCheckoutData] = useState({
    cardNumber: '',
    address: ''
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  // ✅ Диагностика - что в объекте пользователя
  useEffect(() => {
    if (user) {
      console.log('User object in Profile:', user);
      console.log('Available user keys:', Object.keys(user));
    }
  }, [user]);

  // ✅ Обработка параметров таба из URL
  useEffect(() => {
    const searchParams = new URLSearchParams(location.search);
    const tab = searchParams.get('tab');

    if (tab && ['cart', 'favorites', 'orders'].includes(tab)) {
      setActiveTab(tab);
    } else {
      setActiveTab('profile');
    }
  }, [location.search]);

  // ✅ Функция для смены таба
  const handleTabChange = (tab) => {
    setActiveTab(tab);
    if (tab === 'profile') {
      navigate('/profile');
    } else {
      navigate(`/profile?tab=${tab}`);
    }
  };

  // ✅ Функция навигации в каталог
  const goToCatalog = () => {
    navigate('/catalog');
  };

  // ✅ Функция для перехода к товару
  const goToProduct = (productId) => {
    navigate(`/product/${productId}`);
  };

  // ✅ Функция для безопасного получения изображения
  const getProductImage = (product) => {
    if (!product || !product.images || product.images.length === 0) {
      return '/images/placeholder.jpg';
    }
    return product.images[0];
  };

  // ✅ Функция оформления заказа
  const handleCheckout = async (e) => {
    e.preventDefault();
    if (cart.length === 0) {
      alert('Корзина пуста!');
      return;
    }

    setIsSubmitting(true);

    try {
      await new Promise(resolve => setTimeout(resolve, 1000));

      const order = createOrder(checkoutData);

      setCheckoutData({
        cardNumber: '',
        address: ''
      });

      alert(`Заказ #${order.id} успешно оформлен!`);
      handleTabChange('orders');

    } catch (error) {
      alert('Произошла ошибка при оформлении заказа');
    } finally {
      setIsSubmitting(false);
    }
  };

  // ✅ Функция отмены заказа
  const handleCancelOrder = (orderId) => {
    if (window.confirm('Вы уверены, что хотите отменить этот заказ?')) {
      cancelOrder(orderId);
      alert('Заказ отменен');
    }
  };

  // ✅ Функция для получения статуса заказа
  const getOrderStatus = (status) => {
    const statuses = {
      pending: { text: 'В обработке', color: 'text-yellow-600', bg: 'bg-yellow-100' },
      completed: { text: 'Завершен', color: 'text-green-600', bg: 'bg-green-100' },
      cancelled: { text: 'Отменен', color: 'text-red-600', bg: 'bg-red-100' }
    };
    return statuses[status] || statuses.pending;
  };

  // ✅ Функция для безопасного получения данных пользователя
  const getUserDisplayName = () => {
    if (!user) return 'Пользователь';

    // Пробуем разные возможные поля
    return user.username || user.name || user.email || user.displayName || 'Пользователь';
  };

  const getUserEmail = () => {
    if (!user) return 'Не указан';
    return user.email || 'Не указан';
  };

  if (!user) {
    return (
      <div className="max-w-md mx-auto mt-16 p-8 text-center">
        <p className="text-lg mb-4">Пожалуйста, войдите в систему</p>
        <button 
          onClick={goToCatalog}
          className="bg-gold-600 text-white px-6 py-3 rounded hover:bg-gold-700"
        >
          Войти / Зарегистрироваться
        </button>
      </div>
    );
  }

  const totalPrice = cart.reduce((sum, item) => sum + (item.price * (item.quantity || 1)), 0);

  return (
    <div className="max-w-6xl mx-auto px-4 py-8">
      <h1 className="text-3xl font-serif font-bold mb-8">Личный кабинет</h1>

      {/* Tabs */}
      <div className="border-b mb-8">
        <div className="flex space-x-8">
          {['profile', 'cart', 'favorites', 'orders'].map(tab => (
            <button
              key={tab}
              onClick={() => handleTabChange(tab)}
              className={`pb-4 px-2 capitalize ${
                activeTab === tab 
                  ? 'border-b-2 border-gold-600 text-gold-600 font-semibold' 
                  : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              {tab === 'profile' ? 'Профиль' : 
               tab === 'cart' ? 'Корзина' : 
               tab === 'favorites' ? 'Понравилось' : 'Мои заказы'}
            </button>
          ))}
        </div>
      </div>

      {/* Profile Tab */}
      {activeTab === 'profile' && (
        <div className="max-w-2xl">
          <div className="bg-white rounded-lg shadow-md p-6">
            <h2 className="text-xl font-semibold mb-4">Информация о профиле</h2>
            <div className="space-y-3">
              {/* ✅ Исправлено: безопасное получение данных пользователя */}
              <p><strong>Имя пользователя:</strong> {getUserDisplayName()}</p>
              <p><strong>Email:</strong> {getUserEmail()}</p>

              {/* Дополнительная информация о пользователе */}
              <p><strong>Количество заказов:</strong> {orders?.length || 0}</p>
              <p><strong>Товаров в избранном:</strong> {favorites?.length || 0}</p>
            </div>

            {/* Отладочная информация (можно удалить после исправления) */}
            <div className="mt-4 p-3 bg-gray-100 rounded text-sm">
              <p className="text-gray-600">Отладочная информация:</p>
              <p className="text-gray-500">Доступные поля: {user ? Object.keys(user).join(', ') : 'нет данных'}</p>
            </div>

            <button
              onClick={() => {
                logout();
                navigate('/');
              }}
              className="mt-6 bg-red-600 hover:bg-red-700 text-white px-6 py-2 rounded"
            >
              Выйти
            </button>
          </div>
        </div>
      )}

      {/* Остальные вкладки остаются без изменений */}
      {/* ... */}
    </div>
  );
};

export default Profile;
